ALTER TABLE public.store_settings ADD COLUMN establishment_name text NOT NULL DEFAULT 'FH Tech', ADD COLUMN logo_url text NOT NULL DEFAULT '';
CREATE TABLE public.dining_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),table_id uuid NOT NULL REFERENCES public.dining_tables(id),label text NOT NULL,started_at timestamptz NOT NULL,closed_at timestamptz,bill_requested_at timestamptz,subtotal numeric NOT NULL DEFAULT 0,service_percentage numeric NOT NULL DEFAULT 0,service_amount numeric NOT NULL DEFAULT 0,total numeric NOT NULL DEFAULT 0,people integer NOT NULL DEFAULT 1);
GRANT SELECT ON public.dining_sessions TO authenticated; GRANT ALL ON public.dining_sessions TO service_role;
ALTER TABLE public.dining_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY team_sessions_read ON public.dining_sessions FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'staff'));
ALTER TABLE public.dining_tables ADD COLUMN current_session_id uuid REFERENCES public.dining_sessions(id);
INSERT INTO public.dining_sessions(table_id,label,started_at) SELECT id,label,session_started_at FROM public.dining_tables;
UPDATE public.dining_tables t SET current_session_id=s.id FROM public.dining_sessions s WHERE s.table_id=t.id;
ALTER TABLE public.orders ADD COLUMN dining_session_id uuid REFERENCES public.dining_sessions(id);
UPDATE public.orders o SET dining_session_id=t.current_session_id FROM public.dining_tables t WHERE o.table_id=t.id AND o.created_at>=t.session_started_at;
CREATE FUNCTION public.assign_dining_session() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.dining_tables; s uuid; BEGIN IF NEW.delivery_method='mesa' THEN SELECT * INTO t FROM public.dining_tables WHERE id=NEW.table_id FOR UPDATE; IF NOT FOUND OR NOT t.active OR NOT (SELECT dine_in_enabled FROM public.store_settings WHERE id=1) THEN RAISE EXCEPTION 'Mesa indisponível'; END IF; s=t.current_session_id; IF s IS NULL THEN INSERT INTO public.dining_sessions(table_id,label,started_at) VALUES(t.id,t.label,t.session_started_at) RETURNING id INTO s; UPDATE public.dining_tables SET current_session_id=s WHERE id=t.id; END IF; NEW.dining_session_id=s; END IF; RETURN NEW; END $$;
CREATE TRIGGER assign_order_session BEFORE INSERT ON public.orders FOR EACH ROW EXECUTE FUNCTION public.assign_dining_session();
CREATE TABLE public.service_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL UNIQUE REFERENCES public.dining_sessions(id),courtesy integer NOT NULL CHECK(courtesy BETWEEN 1 AND 5),speed integer NOT NULL CHECK(speed BETWEEN 1 AND 5),experience integer NOT NULL CHECK(experience BETWEEN 1 AND 5),message text NOT NULL DEFAULT '' CHECK(length(message)<=1000),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.service_reviews TO authenticated; GRANT ALL ON public.service_reviews TO service_role;
ALTER TABLE public.service_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY director_service_reviews ON public.service_reviews FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.submit_service_review(_order uuid,_token uuid,_courtesy integer,_speed integer,_experience integer,_message text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s uuid; r uuid; BEGIN SELECT ds.id INTO s FROM public.orders o JOIN public.dining_sessions ds ON ds.id=o.dining_session_id WHERE o.id=_order AND o.review_token=_token AND o.delivery_method='mesa' AND o.status<>'cancelado' AND (ds.bill_requested_at IS NOT NULL OR ds.closed_at IS NOT NULL); IF s IS NULL THEN RAISE EXCEPTION 'Avaliação indisponível'; END IF; INSERT INTO public.service_reviews(session_id,courtesy,speed,experience,message) VALUES(s,_courtesy,_speed,_experience,_message) RETURNING id INTO r; RETURN r; END $$;
REVOKE ALL ON FUNCTION public.submit_service_review(uuid,uuid,integer,integer,integer,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.submit_service_review(uuid,uuid,integer,integer,integer,text) TO service_role;
CREATE FUNCTION public.close_dining_session(_table uuid,_session uuid,_subtotal numeric,_service numeric,_people integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.dining_tables; amount numeric; next_id uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Acesso exclusivo da direção'; END IF; IF _service<0 OR _service>100 OR _people<1 OR _people>30 THEN RAISE EXCEPTION 'Valores inválidos'; END IF; SELECT * INTO t FROM public.dining_tables WHERE id=_table FOR UPDATE; IF NOT FOUND OR t.current_session_id IS DISTINCT FROM _session THEN RAISE EXCEPTION 'Comanda já encerrada; atualize a tela'; END IF; SELECT coalesce(sum(total),0) INTO amount FROM public.orders WHERE dining_session_id=_session AND status<>'cancelado'; IF amount IS DISTINCT FROM _subtotal THEN RAISE EXCEPTION 'Consumo alterado; confira a conta novamente'; END IF; UPDATE public.dining_sessions SET closed_at=now(),subtotal=amount,service_percentage=_service,service_amount=round(amount*_service/100,2),total=amount+round(amount*_service/100,2),people=_people WHERE id=_session AND closed_at IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Comanda já encerrada'; END IF; UPDATE public.waiter_calls SET resolved_at=now() WHERE table_id=t.id AND resolved_at IS NULL; INSERT INTO public.dining_sessions(table_id,label,started_at) VALUES(t.id,t.label,now()) RETURNING id INTO next_id; UPDATE public.dining_tables SET current_session_id=next_id,session_started_at=now() WHERE id=t.id; RETURN _session; END $$;
REVOKE ALL ON FUNCTION public.close_dining_session(uuid,uuid,numeric,numeric,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.close_dining_session(uuid,uuid,numeric,numeric,integer) TO authenticated;
CREATE OR REPLACE FUNCTION public.grant_first_director() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RETURN NEW; END $$;